import{_ as t,o as r,c as a,a3 as i}from"./chunks/framework.BrO6lPIi.js";const d=JSON.parse('{"title":"项目概览与快速开始","description":"AI Helper 是一个让大语言模型真正操作网页的开源浏览器扩展。","frontmatter":{"title":"项目概览与快速开始","description":"AI Helper 是一个让大语言模型真正操作网页的开源浏览器扩展。"},"headers":[],"relativePath":"项目概览与快速开始/index.md","filePath":"项目概览与快速开始/index.md","lastUpdated":null}'),l={name:"项目概览与快速开始/index.md"};function n(o,e,g,s,c,h){return r(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="项目概览与快速开始" tabindex="-1">项目概览与快速开始 <a class="header-anchor" href="#项目概览与快速开始" aria-label="Permalink to &quot;项目概览与快速开始&quot;">​</a></h1><details class="details custom-block"><summary>本文引用的源码文件</summary><p><strong>本文引用的文件</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/README.md" target="_blank" rel="noreferrer">README.md</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/README.zh-CN.md" target="_blank" rel="noreferrer">README.zh-CN.md</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/manifest.json" target="_blank" rel="noreferrer">manifest.json</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/package.json" target="_blank" rel="noreferrer">package.json</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/package.json" target="_blank" rel="noreferrer">agent/package.json</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/config/version.json" target="_blank" rel="noreferrer">src/config/version.json</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/.github/workflows/release.yml" target="_blank" rel="noreferrer">.github/workflows/release.yml</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js" target="_blank" rel="noreferrer">src/background/local-agent-client.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/agent-dispatcher.js" target="_blank" rel="noreferrer">src/background/agent-dispatcher.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/shared/agent-defaults.js" target="_blank" rel="noreferrer">src/shared/agent-defaults.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js" target="_blank" rel="noreferrer">agent/src/server.js</a></li></ul></details><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ol><li><a href="#引言">引言</a></li><li><a href="#项目结构">项目结构</a></li><li><a href="#核心组件">核心组件</a></li><li><a href="#架构总览">架构总览</a></li><li><a href="#详细组件分析">详细组件分析</a></li><li><a href="#依赖关系分析">依赖关系分析</a></li><li><a href="#性能与运行时约束">性能与运行时约束</a></li><li><a href="#安装指南与系统要求">安装指南与系统要求</a></li><li><a href="#快速开始">快速开始</a></li><li><a href="#基本使用示例">基本使用示例</a></li><li><a href="#扩展端与-agent-端通信机制">扩展端与 Agent 端通信机制</a></li><li><a href="#版本同步策略">版本同步策略</a></li><li><a href="#常见故障排查">常见故障排查</a></li><li><a href="#开源协议贡献方式与社区支持">开源协议、贡献方式与社区支持</a></li><li><a href="#结论">结论</a></li></ol><h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to &quot;引言&quot;">​</a></h2><p>AI Helper 是一个让大语言模型真正操作网页的开源浏览器扩展。它不只是聊天，还能点击、填写表单、拖拽、上传文件、执行终端命令，并通过 MCP 协议动态扩展工具；可选本地 Agent 服务进一步提供文件读写、命令执行、长期记忆与知识库检索能力。</p><p>项目的核心价值可以概括为：</p><ul><li><strong>可操作的 AI 助手</strong>：从“读网页”升级到“亲手操作网页”。</li><li><strong>双进程架构</strong>：Chrome 扩展端负责用户界面、页面交互与任务编排；独立 Node.js Agent 服务负责本地文件系统、命令执行、RAG 知识库和外部工具集成。</li><li><strong>可控且可扩展</strong>：内置 40+ 工具、Skill 技能系统、MCP 协议、多智能体协作、定时任务、审计日志与回收站等生产级能力。</li><li><strong>数据本地优先</strong>：知识库索引和本地文件操作运行在用户本机，便于隐私控制和离线场景。</li></ul><p>当前文档以版本 <strong>2.3.1</strong> 为准，对应扩展端 <code>package.json</code>、Agent 包 <code>ai-helper-agent</code>、Manifest 版本号以及构建产物中的版本信息保持一致。</p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/README.md#L39-L75" target="_blank" rel="noreferrer">README.md#L39-L75</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/README.zh-CN.md#L39-L75" target="_blank" rel="noreferrer">README.zh-CN.md#L39-L75</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/package.json#L1-L10" target="_blank" rel="noreferrer">package.json#L1-L10</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/package.json#L1-L10" target="_blank" rel="noreferrer">agent/package.json#L1-L10</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/manifest.json#L1-L10" target="_blank" rel="noreferrer">manifest.json#L1-L10</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/config/version.json#L1-L7" target="_blank" rel="noreferrer">src/config/version.json#L1-L7</a></li></ul><h2 id="项目结构" tabindex="-1">项目结构 <a class="header-anchor" href="#项目结构" aria-label="Permalink to &quot;项目结构&quot;">​</a></h2><p>仓库采用“扩展端 + Agent 子工程”的组织方式：</p><ul><li>根目录是 Chrome 扩展工程，包含 Manifest V3 配置、Vite 构建脚本、背景脚本、内容脚本、侧边栏、选项页、共享模块和测试。</li><li><code>agent/</code> 是独立的 Node.js 代理服务工程，暴露 HTTP/WebSocket API，并提供 MCP、Skill、RAG、命令执行、文件管理、安全策略和日志子系统。</li><li><code>docs/</code> 存放产品文档、架构图、商店素材、文章和演示资源。</li><li><code>scripts/</code> 包含构建、打包、主题审计、图标生成等工程脚本。</li><li><code>test/</code> 是扩展端的单元测试与端到端测试；Agent 端测试位于 <code>agent/test/</code>。</li></ul><pre class="mermaid">graph TB
Root[&quot;仓库根目录&lt;br/&gt;Chrome 扩展工程&quot;] --&gt; Src[&quot;src/&lt;br/&gt;扩展源代码&quot;]
Root --&gt; Docs[&quot;docs/&lt;br/&gt;文档与素材&quot;]
Root --&gt; Scripts[&quot;scripts/&lt;br/&gt;构建与发布脚本&quot;]
Root --&gt; Test[&quot;test/&lt;br/&gt;扩展端测试&quot;]
Root --&gt; Agent[&quot;agent/&lt;br/&gt;Node.js 代理服务&quot;]
Agent --&gt; AgentSrc[&quot;agent/src/&lt;br/&gt;HTTP 服务器、MCP、Skill、RAG、安全、日志&quot;]
Agent --&gt; AgentTest[&quot;agent/test/&lt;br/&gt;代理端测试&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/manifest.json#L1-L76" target="_blank" rel="noreferrer">manifest.json#L1-L76</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/package.json#L6-L24" target="_blank" rel="noreferrer">package.json#L6-L24</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/package.json#L1-L25" target="_blank" rel="noreferrer">agent/package.json#L1-L25</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/manifest.json#L1-L76" target="_blank" rel="noreferrer">manifest.json#L1-L76</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/package.json#L1-L47" target="_blank" rel="noreferrer">package.json#L1-L47</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/package.json#L1-L67" target="_blank" rel="noreferrer">agent/package.json#L1-L67</a></li></ul><h2 id="核心组件" tabindex="-1">核心组件 <a class="header-anchor" href="#核心组件" aria-label="Permalink to &quot;核心组件&quot;">​</a></h2><p>本项目由两个主要进程组成：</p><table tabindex="0"><thead><tr><th>组件</th><th>职责</th><th>关键入口或文件</th><th>技术要点</th></tr></thead><tbody><tr><td>Chrome 扩展端</td><td>用户界面、页面注入、工具调用、会话管理、调度、通知、主题与国际化</td><td><code>manifest.json</code>、<code>src/background/index.js</code>、<code>src/side_panel.html</code>、<code>src/options.html</code></td><td>Manifest V3 Service Worker、Side Panel、Content Script、MV3 生命周期保活</td></tr><tr><td>本地 Agent 服务</td><td>文件读写、命令执行、MCP 工具注册、Skill 执行、RAG 知识库、认证与日志</td><td><code>agent/src/server.js</code>、<code>agent/package.json</code></td><td>Node.js HTTP/WebSocket、CORS 白名单、Bearer Token、路径与命令安全分级</td></tr></tbody></table><p>扩展端通过本地 HTTP 和 WebSocket 调用 Agent 提供的能力；Agent 修改源码后必须重启进程，新接口才会生效。</p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/manifest.json#L47-L53" target="_blank" rel="noreferrer">manifest.json#L47-L53</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1-L23" target="_blank" rel="noreferrer">agent/src/server.js#L1-L23</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L388-L425" target="_blank" rel="noreferrer">agent/src/server.js#L388-L425</a></li></ul><h2 id="架构总览" tabindex="-1">架构总览 <a class="header-anchor" href="#架构总览" aria-label="Permalink to &quot;架构总览&quot;">​</a></h2><p>AI Helper 的双进程架构可以理解为“浏览器内的智能助手 + 本机上的可信代理”：</p><pre class="mermaid">graph TB
User[&quot;用户&quot;] --&gt; SidePanel[&quot;侧边栏界面&lt;br/&gt;side_panel.html&quot;]
SidePanel --&gt; Background[&quot;Background Service Worker&lt;br/&gt;src/background/index.js&quot;]
Background --&gt; ContentScript[&quot;Content Script&lt;br/&gt;src/content/index.js&quot;]
Background --&gt; LocalAgentClient[&quot;本地 Agent 客户端&lt;br/&gt;src/background/local-agent-client.js&quot;]
LocalAgentClient --&gt; AgentServer[&quot;Agent HTTP/WebSocket 服务器&lt;br/&gt;agent/src/server.js&quot;]
AgentServer --&gt; FileSystem[&quot;本地文件系统&quot;]
AgentServer --&gt; Shell[&quot;系统命令执行&quot;]
AgentServer --&gt; RAG[&quot;RAG 知识库&quot;]
AgentServer --&gt; MCP[&quot;MCP 工具注册与调用&quot;]
AgentServer --&gt; Skill[&quot;Skill 技能系统&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/manifest.json#L36-L53" target="_blank" rel="noreferrer">manifest.json#L36-L53</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L40-L93" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L40-L93</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1-L56" target="_blank" rel="noreferrer">agent/src/server.js#L1-L56</a></li></ul><p>该架构的关键设计原则包括：</p><ul><li>扩展端专注浏览器上下文、UI 和任务编排。</li><li>Agent 端专注本地资源和外部系统能力。</li><li>两端通过明确的 API 契约通信，而不是直接共享内存。</li><li>安全边界由 CORS、Origin 校验、Bearer Token、路径白名单和命令安全检查共同构成。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L40-L93" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L40-L93</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L235-L266" target="_blank" rel="noreferrer">agent/src/server.js#L235-L266</a></li></ul><h2 id="详细组件分析" tabindex="-1">详细组件分析 <a class="header-anchor" href="#详细组件分析" aria-label="Permalink to &quot;详细组件分析&quot;">​</a></h2><h3 id="chrome-扩展端" tabindex="-1">Chrome 扩展端 <a class="header-anchor" href="#chrome-扩展端" aria-label="Permalink to &quot;Chrome 扩展端&quot;">​</a></h3><p>扩展端基于 Manifest V3，核心职责包括：</p><ul><li>定义扩展权限、内容脚本、Service Worker、选项页和侧边栏。</li><li>管理用户会话、消息流、工具调用、截图、调试器、调度器和通知。</li><li>通过 <code>local-agent-client.js</code> 封装与 Agent 的 HTTP/WebSocket 通信。</li><li>提供内置 Agent 模板和多 Agent 调度能力。</li></ul><pre class="mermaid">classDiagram
class BackgroundService {
+启动服务Worker
+处理扩展消息
+管理会话状态
+协调工具执行
+触发通知
}
class LocalAgentClient {
+pairWithAgent()
+agentRequest()
+agentGet()
+uploadFile()
+execCommand()
+createExecWebSocket()
+getMcpTools()
+callMcpTool()
}
class AgentDispatcher {
+executeDispatchSubAgent()
+loadAgent()
+buildSubAgentPrompt()
}
class SharedAgentDefaults {
+BUILTIN_AGENTS
+AGENT_TEMPLATES
+generateAgentId()
}
BackgroundService --&gt; LocalAgentClient : &quot;调用&quot;
BackgroundService --&gt; AgentDispatcher : &quot;派生子任务&quot;
AgentDispatcher --&gt; SharedAgentDefaults : &quot;读取内置Agent&quot;
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/manifest.json#L47-L53" target="_blank" rel="noreferrer">manifest.json#L47-L53</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L40-L93" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L40-L93</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/agent-dispatcher.js#L1-L28" target="_blank" rel="noreferrer">src/background/agent-dispatcher.js#L1-L28</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/shared/agent-defaults.js#L1-L21" target="_blank" rel="noreferrer">src/shared/agent-defaults.js#L1-L21</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/manifest.json#L1-L76" target="_blank" rel="noreferrer">manifest.json#L1-L76</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L40-L93" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L40-L93</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/agent-dispatcher.js#L1-L28" target="_blank" rel="noreferrer">src/background/agent-dispatcher.js#L1-L28</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/shared/agent-defaults.js#L1-L21" target="_blank" rel="noreferrer">src/shared/agent-defaults.js#L1-L21</a></li></ul><h3 id="本地-agent-服务" tabindex="-1">本地 Agent 服务 <a class="header-anchor" href="#本地-agent-服务" aria-label="Permalink to &quot;本地 Agent 服务&quot;">​</a></h3><p>Agent 服务是扩展端能力的延伸，核心职责包括：</p><ul><li>启动 HTTP 服务器并路由 <code>/api/*</code> 请求。</li><li>实现配对认证、健康检查、心跳、重启、更新和关闭。</li><li>提供文件读写、目录列表、搜索、ZIP 打包、流式上传。</li><li>执行系统命令，支持异步、等待、停止、分离模式。</li><li>注册 MCP 工具、Skill 技能、RAG 知识库。</li><li>输出结构化日志，支持审计与安全事件记录。</li></ul><pre class="mermaid">flowchart TD
Start[&quot;Agent 进程启动&quot;] --&gt; LoadConfig[&quot;加载配置&quot;]
LoadConfig --&gt; InitSearch[&quot;初始化搜索工具检测&quot;]
InitSearch --&gt; InitRAG[&quot;检测 RAG 可用性&quot;]
InitRAG --&gt; CreateServer[&quot;创建 HTTP 服务器&quot;]
CreateServer --&gt; HandleRequest[&quot;处理 /api/* 请求&quot;]
HandleRequest --&gt; PairCheck{&quot;是否配对接口？&quot;}
PairCheck --&gt; |是| PairHandler[&quot;处理 /api/pair&quot;]
PairCheck --&gt; |否| AuthCheck{&quot;是否需要认证？&quot;}
AuthCheck --&gt; |否| PublicHandler[&quot;公开接口：status、pair 等&quot;]
AuthCheck --&gt; |是| TokenVerify[&quot;验证 Bearer Token&quot;]
TokenVerify --&gt; RouteHandler[&quot;路由到具体功能&quot;]
RouteHandler --&gt; FileOps[&quot;文件操作&quot;]
RouteHandler --&gt; ExecOps[&quot;命令执行&quot;]
RouteHandler --&gt; McpOps[&quot;MCP 工具&quot;]
RouteHandler --&gt; SkillOps[&quot;Skill 技能&quot;]
RouteHandler --&gt; RagOps[&quot;RAG 知识库&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L388-L425" target="_blank" rel="noreferrer">agent/src/server.js#L388-L425</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L471-L548" target="_blank" rel="noreferrer">agent/src/server.js#L471-L548</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L751-L800" target="_blank" rel="noreferrer">agent/src/server.js#L751-L800</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1-L56" target="_blank" rel="noreferrer">agent/src/server.js#L1-L56</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L388-L425" target="_blank" rel="noreferrer">agent/src/server.js#L388-L425</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L471-L548" target="_blank" rel="noreferrer">agent/src/server.js#L471-L548</a></li></ul><h3 id="子代理调度与内置-agent" tabindex="-1">子代理调度与内置 Agent <a class="header-anchor" href="#子代理调度与内置-agent" aria-label="Permalink to &quot;子代理调度与内置 Agent&quot;">​</a></h3><p>扩展端支持主 Agent 派生子 Agent，用于分工完成复杂任务。调度器会：</p><ul><li>限制嵌套深度，防止 ReAct 循环无限递归。</li><li>加载内置或自定义 Agent 定义。</li><li>根据 Agent 的工具集合和技能提示词构建系统提示。</li><li>使用派生 sessionId 隔离子 Agent 的信令与日志。</li><li>对返回结果进行 token 预算截断。</li></ul><pre class="mermaid">sequenceDiagram
participant Main as &quot;主 Agent&quot;
participant Dispatcher as &quot;AgentDispatcher&quot;
participant Model as &quot;大模型 API&quot;
participant Tools as &quot;工具集合&quot;
Main-&gt;&gt;Dispatcher : 调用 dispatch_task
Dispatcher-&gt;&gt;Dispatcher : 检查嵌套深度
Dispatcher-&gt;&gt;Dispatcher : 加载子 Agent 定义
Dispatcher-&gt;&gt;Tools : 获取子 Agent 工具
Dispatcher-&gt;&gt;Model : 发送带系统提示的消息
Model--&gt;&gt;Dispatcher : 工具调用或最终答案
Dispatcher-&gt;&gt;Tools : 执行工具如有
Tools--&gt;&gt;Dispatcher : 工具结果
Dispatcher--&gt;&gt;Main : 返回子 Agent 执行结果
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/agent-dispatcher.js#L100-L155" target="_blank" rel="noreferrer">src/background/agent-dispatcher.js#L100-L155</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/agent-dispatcher.js#L157-L218" target="_blank" rel="noreferrer">src/background/agent-dispatcher.js#L157-L218</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/shared/agent-defaults.js#L6-L21" target="_blank" rel="noreferrer">src/shared/agent-defaults.js#L6-L21</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/agent-dispatcher.js#L1-L28" target="_blank" rel="noreferrer">src/background/agent-dispatcher.js#L1-L28</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/agent-dispatcher.js#L100-L218" target="_blank" rel="noreferrer">src/background/agent-dispatcher.js#L100-L218</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/shared/agent-defaults.js#L1-L145" target="_blank" rel="noreferrer">src/shared/agent-defaults.js#L1-L145</a></li></ul><h2 id="依赖关系分析" tabindex="-1">依赖关系分析 <a class="header-anchor" href="#依赖关系分析" aria-label="Permalink to &quot;依赖关系分析&quot;">​</a></h2><p>扩展端与 Agent 端的依赖关系不是代码导入关系，而是运行时通信契约：</p><pre class="mermaid">graph LR
Extension[&quot;Chrome 扩展&lt;br/&gt;manifest_version=3&quot;] --&gt; Client[&quot;LocalAgentClient&lt;br/&gt;HTTP/WebSocket 客户端&quot;]
Client --&gt; Server[&quot;Agent 服务器&lt;br/&gt;/api/* 路由&quot;]
Server --&gt; Security[&quot;安全策略&lt;br/&gt;路径/命令校验&quot;]
Server --&gt; Memory[&quot;长期记忆&quot;]
Server --&gt; RAG[&quot;RAG 知识库&quot;]
Server --&gt; MCP[&quot;MCP 工具&quot;]
Server --&gt; Skill[&quot;Skill 技能&quot;]
Server --&gt; Logger[&quot;日志与审计&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/manifest.json#L1-L10" target="_blank" rel="noreferrer">manifest.json#L1-L10</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L40-L93" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L40-L93</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1-L56" target="_blank" rel="noreferrer">agent/src/server.js#L1-L56</a></li></ul><p>需要注意：</p><ul><li>扩展端不直接访问 Agent 的内部模块，只通过 API 调用。</li><li>Agent 内部模块之间耦合较高，例如 server.js 同时引入安全、日志、MCP、Skill、RAG、命令执行等。</li><li>扩展端与 Agent 端的版本号应保持一致，避免契约不一致。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L40-L93" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L40-L93</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1-L56" target="_blank" rel="noreferrer">agent/src/server.js#L1-L56</a></li></ul><h2 id="性能与运行时约束" tabindex="-1">性能与运行时约束 <a class="header-anchor" href="#性能与运行时约束" aria-label="Permalink to &quot;性能与运行时约束&quot;">​</a></h2><ul><li><strong>Service Worker 生命周期</strong>：Chrome MV3 的 Service Worker 可能被空闲终止，需要保活机制；background 与 side panel 的消息传递是常见故障点。</li><li><strong>Agent 进程重启</strong>：Agent 源码修改后必须重启进程，新接口才生效；服务端提供 <code>/api/agent/restart</code> 和 <code>/api/agent/update</code> 接口。</li><li><strong>请求超时</strong>：扩展端对 HTTP 请求设置默认超时，WebSocket 连接空闲超时由调用方统一管理，避免双重超时冲突。</li><li><strong>Token 预算管理</strong>：扩展端按 Token 数而非消息数截断上下文，避免拆分 tool_calls 与 tool 消息。</li><li><strong>文件大小限制</strong>：Agent 对 JSON body、流式上传、文件读取分别设置大小上限，防止内存爆炸。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L393-L443" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L393-L443</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L652-L728" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L652-L728</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L132-L137" target="_blank" rel="noreferrer">agent/src/server.js#L132-L137</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L555-L603" target="_blank" rel="noreferrer">agent/src/server.js#L555-L603</a></li></ul><h2 id="安装指南与系统要求" tabindex="-1">安装指南与系统要求 <a class="header-anchor" href="#安装指南与系统要求" aria-label="Permalink to &quot;安装指南与系统要求&quot;">​</a></h2><p>官方安装渠道以 GitHub Releases 自动构建产物为主：</p><ul><li>从 Chrome Web Store 或 Microsoft Edge Add-ons 商店安装。</li><li>Chromium 用户可从 GitHub Releases 下载 <code>ai-helper-*.zip</code>，解压后在开发者模式下加载已解压扩展程序。</li><li>开发者可从源码构建，但推荐普通用户直接使用官方构建产物。</li></ul><p>系统要求：</p><ul><li>Chrome / Edge / Chromium 114+，因为需要使用 Side Panel API。</li><li>若启用本地 Agent 能力，需要 Node.js 环境安装 <code>ai-helper-agent</code>。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/README.md#L87-L94" target="_blank" rel="noreferrer">README.md#L87-L94</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/README.zh-CN.md#L87-L94" target="_blank" rel="noreferrer">README.zh-CN.md#L87-L94</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/package.json#L1-L10" target="_blank" rel="noreferrer">package.json#L1-L10</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/package.json#L44-L46" target="_blank" rel="noreferrer">agent/package.json#L44-L46</a></li></ul><h2 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h2><p>推荐的新手流程如下：</p><ol><li><strong>安装扩展</strong>：从应用商店或 GitHub Releases 安装。</li><li><strong>打开侧边栏</strong>：使用快捷键或扩展图标打开侧边栏。</li><li><strong>配置大模型厂商</strong>：在选项页添加 OpenAI 兼容端点和密钥，保存多个厂商配置。</li><li><strong>可选：启动本地 Agent</strong>：一键安装代理端或使用命令行启动，将配对码填入选项页 → Agent。</li></ol><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/README.md#L87-L94" target="_blank" rel="noreferrer">README.md#L87-L94</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/README.zh-CN.md#L87-L94" target="_blank" rel="noreferrer">README.zh-CN.md#L87-L94</a></li></ul><h2 id="基本使用示例" tabindex="-1">基本使用示例 <a class="header-anchor" href="#基本使用示例" aria-label="Permalink to &quot;基本使用示例&quot;">​</a></h2><p>以下是几个适合入门的典型场景：</p><table tabindex="0"><thead><tr><th>场景</th><th>说明</th><th>相关能力</th></tr></thead><tbody><tr><td>网页信息提取</td><td>让 AI 读取当前标签页内容，总结长文、表格或链接列表</td><td>页面内容、元素查询、数据提取</td></tr><tr><td>任务自动化</td><td>自动点击、填表、滚动、上传文件，甚至处理弹窗</td><td>页面交互、表单填充、文件上传</td></tr><tr><td>知识检索</td><td>导入 PDF、Word、Excel、PPT、Markdown、HTML、CSV，构建本地知识库并提问</td><td>RAG、混合检索、引用溯源</td></tr><tr><td>本地文件与命令</td><td>让 AI 读取本地文件、列出目录、执行终端命令</td><td>Agent 文件 API、命令执行、安全分级</td></tr><tr><td>定时任务</td><td>每天固定时间针对某个 URL 重跑指令，结果写入指定会话</td><td>调度器、通知、会话管理</td></tr></tbody></table><p>这些场景在 README 中都有明确描述，可作为上手起点。</p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/README.md#L39-L85" target="_blank" rel="noreferrer">README.md#L39-L85</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/README.zh-CN.md#L39-L85" target="_blank" rel="noreferrer">README.zh-CN.md#L39-L85</a></li></ul><h2 id="扩展端与-agent-端通信机制" tabindex="-1">扩展端与 Agent 端通信机制 <a class="header-anchor" href="#扩展端与-agent-端通信机制" aria-label="Permalink to &quot;扩展端与 Agent 端通信机制&quot;">​</a></h2><p>扩展端通过 <code>local-agent-client.js</code> 封装与 Agent 的通信，核心契约包括：</p><table tabindex="0"><thead><tr><th>类别</th><th>端点或行为</th><th>用途</th></tr></thead><tbody><tr><td>配对与会话</td><td><code>/api/pair</code>、<code>/api/status</code>、<code>/api/status/detail</code></td><td>配对认证、健康检查、平台信息</td></tr><tr><td>文件系统</td><td><code>/api/fs/read</code>、<code>/api/fs/write</code>、<code>/api/fs/list</code>、<code>/api/fs/delete</code>、<code>/api/files/upload</code></td><td>文件读写、目录操作、上传</td></tr><tr><td>命令执行</td><td><code>/api/exec</code>、<code>/api/exec/stop</code></td><td>异步执行、等待结果、停止进程</td></tr><tr><td>MCP</td><td><code>/api/mcp/tools</code>、<code>/api/mcp/call</code>、<code>/api/mcp/servers/*</code></td><td>工具发现与调用</td></tr><tr><td>Skill</td><td><code>/api/skill/list</code>、<code>/api/skill/run</code>、<code>/api/skill/import*</code></td><td>技能管理与执行</td></tr><tr><td>实时输出</td><td>WebSocket</td><td>命令执行的实时流式输出</td></tr></tbody></table><p>通信安全机制包括：</p><ul><li>仅允许 Chrome 扩展来源跨域访问。</li><li>需认证的接口使用 <code>Authorization: Bearer &lt;token&gt;</code>。</li><li>配对码一次性使用，已配对后不再下发敏感信息。</li><li>心跳接口仅刷新在线状态，不泄露宿主敏感信息。</li></ul><pre class="mermaid">sequenceDiagram
participant UI as &quot;扩展侧边栏&quot;
participant Client as &quot;LocalAgentClient&quot;
participant Server as &quot;Agent 服务器&quot;
UI-&gt;&gt;Client : 发起配对请求
Client-&gt;&gt;Server : POST /api/pair
Server--&gt;&gt;Client : 返回 token
Client-&gt;&gt;Server : GET /api/status
Server--&gt;&gt;Client : 返回版本与平台信息
UI-&gt;&gt;Client : 调用文件/命令/MCP/Skill/RAG
Client-&gt;&gt;Server : 带 Bearer Token 的 HTTP 请求
Server--&gt;&gt;Client : 返回结构化结果
Client--&gt;&gt;UI : 渲染结果或错误提示
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L40-L93" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L40-L93</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L275-L330" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L275-L330</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L471-L548" target="_blank" rel="noreferrer">agent/src/server.js#L471-L548</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L40-L93" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L40-L93</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L275-L330" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L275-L330</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L471-L548" target="_blank" rel="noreferrer">agent/src/server.js#L471-L548</a></li></ul><h2 id="版本同步策略" tabindex="-1">版本同步策略 <a class="header-anchor" href="#版本同步策略" aria-label="Permalink to &quot;版本同步策略&quot;">​</a></h2><p>项目采用“扩展端与 Agent 端版本号保持同步”的策略：</p><ul><li>扩展端版本定义在根 <code>package.json</code> 和 <code>manifest.json</code> 中。</li><li>Agent 端版本定义在 <code>agent/package.json</code> 中。</li><li>构建产物中的版本信息来自 <code>src/config/version.json</code>。</li><li>CI 通过 <code>.github/workflows/release.yml</code> 构建扩展 zip 并发布到 GitHub Releases。</li></ul><p>建议维护者：</p><ul><li>升级版本时同步更新扩展端与 Agent 端版本号。</li><li>发布前确认 <code>npm run build:silent</code> 能成功构建。</li><li>用户安装时应优先选择与扩展版本匹配的 Agent 版本。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/package.json#L1-L10" target="_blank" rel="noreferrer">package.json#L1-L10</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/manifest.json#L1-L10" target="_blank" rel="noreferrer">manifest.json#L1-L10</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/package.json#L1-L10" target="_blank" rel="noreferrer">agent/package.json#L1-L10</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/config/version.json#L1-L7" target="_blank" rel="noreferrer">src/config/version.json#L1-L7</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/.github/workflows/release.yml#L55-L127" target="_blank" rel="noreferrer">.github/workflows/release.yml#L55-L127</a></li></ul><h2 id="常见故障排查" tabindex="-1">常见故障排查 <a class="header-anchor" href="#常见故障排查" aria-label="Permalink to &quot;常见故障排查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>可能原因</th><th>处理建议</th></tr></thead><tbody><tr><td>侧边栏打不开</td><td>Service Worker 被终止或消息未正确传递</td><td>重新打开侧边栏，检查 background 与 side panel 消息</td></tr><tr><td>Agent 显示未配对</td><td>未输入配对码或 Agent 未启动</td><td>启动 Agent，复制配对码到选项页 → Agent</td></tr><tr><td>文件操作失败</td><td>路径不在允许范围或 Agent 不可达</td><td>检查工作目录、允许路径、Agent 是否运行</td></tr><tr><td>命令执行无输出</td><td>WebSocket 连接断开或超时</td><td>查看命令执行日志，确认 Agent 进程存活</td></tr><tr><td>知识库不可用</td><td>RAG 依赖未安装或 Node 版本不满足</td><td>检查 Node.js 版本，按提示恢复 RAG 依赖</td></tr><tr><td>主题异常</td><td>样式未使用 CSS 变量 Token 体系</td><td>遵循主题 Token 规范，避免硬编码色值</td></tr></tbody></table><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L393-L443" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L393-L443</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L471-L548" target="_blank" rel="noreferrer">agent/src/server.js#L471-L548</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L555-L603" target="_blank" rel="noreferrer">agent/src/server.js#L555-L603</a></li></ul><h2 id="开源协议、贡献方式与社区支持" tabindex="-1">开源协议、贡献方式与社区支持 <a class="header-anchor" href="#开源协议、贡献方式与社区支持" aria-label="Permalink to &quot;开源协议、贡献方式与社区支持&quot;">​</a></h2><ul><li><strong>开源协议</strong>：MIT License。</li><li><strong>贡献方式</strong>：欢迎提交 PR，建议在动手前阅读架构总览文档。</li><li><strong>社区支持</strong>：GitHub Discussions 和 Issues，每个 Issue 会在 24 小时内回复。</li><li><strong>文档渠道</strong>：中文文档、英文文档、Wiki、文档站和产品介绍文档。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/README.md#L106-L131" target="_blank" rel="noreferrer">README.md#L106-L131</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/README.zh-CN.md#L106-L131" target="_blank" rel="noreferrer">README.zh-CN.md#L106-L131</a></li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>AI Helper 的核心价值在于把“聊天型 AI”升级为“可操作、可编排、可审计”的浏览器智能助手。其双进程架构清晰分离了浏览器上下文和本地系统能力，既降低了扩展端的权限风险，又保留了强大的本地执行能力。对于初学者，可以从网页信息提取和表单自动化入手；对于有经验的开发者，可以深入 MCP、Skill、RAG、多 Agent 协作和 Agent 安全策略。</p><p>在使用时，请始终注意：</p><ul><li>优先通过官方渠道安装扩展和 Agent。</li><li>保持扩展端与 Agent 端版本一致。</li><li>理解 Service Worker 生命周期和 Agent 进程重启约束。</li><li>使用内置的安全策略、回收站和审计日志保护本地数据。</li></ul>`,119)])])}const p=t(l,[["render",n]]);export{d as __pageData,p as default};
